import type {
  TooltipProps,
  TooltipTriggerProps,
  TooltipContentProps,
  TooltipHotkeyProps,
} from "./tooltip.types";

import React, { cloneElement, forwardRef, useCallback } from "react";
import { clsx } from "clsx";
import { useTheme } from "@theme";
import { FloatingArrow, FloatingPortal, type ReferenceType } from "@floating-ui/react";

import { TooltipClasses, StyledTooltip } from "./tooltip.styles";
import {
  useTooltip,
  UseTooltipOptions,
  TooltipContext,
  useTooltipContext,
} from "./hooks/use-tooltip";

const TooltipRoot: React.FC<TooltipProps> = ({
  children,
  arrow = true,
  position = "top",
  enterDelay = 0,
  leaveDelay = 0,
  open: controlledOpen,
  onOpenChange,
  offset = 8,
  showOnHover = true,
  variant = "default",
  styleSlots,
}) => {
  const hookOptions: UseTooltipOptions = {
    position,
    enterDelay,
    leaveDelay,
    open: controlledOpen,
    onOpenChange,
    showOnHover,
    arrow,
    variant,
    offset,
    styleSlots,
  };

  const contextValue = useTooltip(hookOptions);

  return <TooltipContext.Provider value={contextValue}>{children}</TooltipContext.Provider>;
};
TooltipRoot.displayName = "Tooltip";

const Trigger = forwardRef<ReferenceType, TooltipTriggerProps>(
  ({ children, className, ...triggerProps }, forwardedRef) => {
    const theme = useTheme();
    const {
      getReferenceProps,
      refs,
      currentOpenState,
      styleSlots: contextStyleSlots,
      variant,
    } = useTooltipContext();

    const childrenArray = React.Children.toArray(children);
    if (childrenArray.length !== 1 || !React.isValidElement(childrenArray[0])) {
      throw new Error("Tooltip.Trigger requires a single valid React element as its child.");
    }
    const childElement = childrenArray[0] as React.ReactElement;

    const setRef = useCallback(
      (node: ReferenceType | null) => {
        refs.setReference(node);
        if (typeof forwardedRef === "function") {
          forwardedRef(node);
        } else if (forwardedRef) {
          (forwardedRef as React.MutableRefObject<ReferenceType | null>).current = node;
        }
      },
      [refs, forwardedRef],
    );

    const referenceProps = getReferenceProps({
      ref: setRef,
    });
    const ariaDescribedBy = referenceProps["aria-describedby"];
    referenceProps["aria-describedby"] = undefined;

    return (
      <StyledTooltip
        className={TooltipClasses.triggerWrapper}
        currentTheme={theme}
        styleSlots={contextStyleSlots}
        variant={variant}
        {...referenceProps}
      >
        {cloneElement(childElement, {
          ...childElement.props,
          className: clsx(childElement.props.className, className),
          "data-tooltip-open": currentOpenState ? "true" : "false",
          ["aria-describedby"]: ariaDescribedBy || undefined,
          ...triggerProps,
        })}
      </StyledTooltip>
    );
  },
);
Trigger.displayName = "Tooltip.Trigger";

const Content = forwardRef<HTMLDivElement, TooltipContentProps>(
  ({ children, className, style, ...contentProps }, forwardedRef) => {
    const {
      refs,
      floatingStyles,
      floatingContext,
      getFloatingProps,
      isMounted,
      showArrow,
      arrowRef,
      actualPlacement,
      styles,
      middlewareData,
      variant,
      styleSlots: contextStyleSlots,
    } = useTooltipContext();
    const theme = useTheme();

    if (!isMounted) return null;

    const { referenceHidden } = middlewareData.hide || {};

    return (
      <FloatingPortal>
        <div
          ref={refs.setFloating}
          style={{
            zIndex: theme?.zIndex?.dynamic,
            ...floatingStyles,
            ...styles,
            ...(style || {}),
            visibility: referenceHidden ? "hidden" : "visible",
          }}
          {...getFloatingProps(contentProps)}
        >
          <StyledTooltip
            ref={forwardedRef}
            className={clsx(TooltipClasses.root, className)}
            currentTheme={theme}
            styleSlots={contextStyleSlots}
            variant={variant}
          >
            {showArrow && (
              <FloatingArrow
                ref={arrowRef}
                className={clsx(TooltipClasses.arrow, contextStyleSlots?.arrow, {
                  [TooltipClasses.arrowTop]: actualPlacement?.includes("top"),
                  [TooltipClasses.arrowBottom]: actualPlacement?.includes("bottom"),
                  [TooltipClasses.arrowLeft]: actualPlacement?.includes("left"),
                  [TooltipClasses.arrowRight]: actualPlacement?.includes("right"),
                })}
                context={floatingContext}
                data-testid="arrow"
              />
            )}
            <span className={clsx(TooltipClasses.content, contextStyleSlots?.content)}>
              {children}
            </span>
          </StyledTooltip>
        </div>
      </FloatingPortal>
    );
  },
);
Content.displayName = "Tooltip.Content";

const Hotkey = forwardRef<HTMLSpanElement, TooltipHotkeyProps>(
  ({ children, className, ...props }, forwardedRef) => (
    <span ref={forwardedRef} className={clsx(TooltipClasses.hotkey, className)} {...props}>
      {children}
    </span>
  ),
);
Hotkey.displayName = "Tooltip.Hotkey";

const Tooltip = Object.assign(TooltipRoot, {
  Trigger,
  Content,
  Hotkey,
});

export default Tooltip;
